import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.Dkj3JE0_.js";const c=JSON.parse('{"title":"CFA レベル II 計画","description":"","frontmatter":{"title":"CFA レベル II 計画"},"headers":[],"relativePath":"jp/blogs/CFA/plan.md","filePath":"jp/blogs/CFA/plan.md"}'),n={name:"jp/blogs/CFA/plan.md"};function i(s,t,d,o,h,p){return l(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="cfa-レベル-ii-学習計画" tabindex="-1">CFA レベル II 学習計画 <a class="header-anchor" href="#cfa-レベル-ii-学習計画" aria-label="Permalink to &quot;CFA レベル II 学習計画&quot;">​</a></h1><blockquote><p><strong>前提：</strong> 試験は <strong>2026 年 11 月 18 日（水）</strong>。<strong>10 月 31 日</strong>までは集中期間（週 <strong>約 40 時間</strong>、FSA 優先）で残りのカリキュラムを終え、<strong>11 月 1〜16 日</strong>は復習と <strong>模試 3〜4 回</strong>、<strong>11 月 17〜18 日</strong>は軽めの学習のみ。模試と復習の期間は削らないこと。</p></blockquote><h2 id="完了の定義" tabindex="-1">完了の定義 <a class="header-anchor" href="#完了の定義" aria-label="Permalink to &quot;完了の定義&quot;">​</a></h2><ul><li>**10 月 31 日（金）**までに、残りの全科目の 1 周目を終える（株式、債券、ポートフォリオ・マネジメント、コーポレート・イシュアー、オルタナティブ、および FSA と倫理の残り）。</li><li>学んだ各モジュールの章末問題を解く。公式とミスをまとめたノートは 1 冊だけにし、2 冊目の教科書にしない。</li><li><strong>時間を計った模試を 3〜4 回</strong>受け（日程は下記）、各回とも受験時間以上をかけて復習する。どの復習週も FSA から。</li><li>時間制限下で繰り返し崩れる科目がない状態で試験週を迎える。11 月 17〜18 日は睡眠を守る。</li></ul><h2 id="現在の重点-2026-年-10-月-14-日時点" tabindex="-1">現在の重点（2026 年 10 月 14 日時点） <a class="header-anchor" href="#現在の重点-2026-年-10-月-14-日時点" aria-label="Permalink to &quot;現在の重点（2026 年 10 月 14 日時点）&quot;">​</a></h2><p><strong>完了（1 周目不要）：</strong> デリバティブ、数量分析。</p><p><strong>一部完了：</strong> 経済学は残り約半分。倫理は進行中——基準 I(C)、I(D)、I(E)、II(A) まで終了。</p><p><strong>進行中：</strong> FSA モジュール 1（企業間投資）、持分法の基本例題（配当後の投資簿価 118）まで。理想の「M1 完了 + M2 開始」の日程から遅れているので、日曜までの夜で取り戻す。</p><p><strong>1 周目未着手：</strong> 株式、債券、ポートフォリオ・マネジメント、コーポレート・イシュアー、オルタナティブ投資。最も弱いのは FSA。</p><p><strong>次の行動：</strong> M1 の章末問題を終える → <strong>M2 従業員報酬</strong> → M3〜M6（遅れを取り戻す間は骨子だけでも可）+ 倫理の残り + 経済学の残り半分を終える。</p><h2 id="週のリズム-平日" tabindex="-1">週のリズム（平日） <a class="header-anchor" href="#週のリズム-平日" aria-label="Permalink to &quot;週のリズム（平日）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ブロック</th><th style="text-align:right;">時間</th><th>内容</th></tr></thead><tbody><tr><td>夜の CFA</td><td style="text-align:right;">20:00–02:00</td><td>メインのカリキュラム学習と演習。</td></tr><tr><td>トレーニング</td><td style="text-align:right;">18:00–20:00</td><td>個人の時間——CFA は入れない。</td></tr><tr><td>週次レポート</td><td style="text-align:right;">月 08:00–10:00</td><td>仕事の事務——CFA は入れない。</td></tr></tbody></table><p>Animus のクイズは <strong>02:00</strong> のノート確認の後か、明示的な一日の締めの後だけ——学習の途中ではやらない。</p><p>CFA ブロック内は <strong>40/60</strong> で配分：読むのは 40% まで、少なくとも 60% は想起・計算・ケース問題の演習に充てる。</p><h2 id="集中ロードマップ" tabindex="-1">集中ロードマップ <a class="header-anchor" href="#集中ロードマップ" aria-label="Permalink to &quot;集中ロードマップ&quot;">​</a></h2><h3 id="フェーズ-1-—-カリキュラムを終える-10-月-12〜31-日-·-週約-40-時間-·-fsa-優先" tabindex="-1">フェーズ 1 — カリキュラムを終える（10 月 12〜31 日 · 週約 40 時間 · FSA 優先） <a class="header-anchor" href="#フェーズ-1-—-カリキュラムを終える-10-月-12〜31-日-·-週約-40-時間-·-fsa-優先" aria-label="Permalink to &quot;フェーズ 1 — カリキュラムを終える（10 月 12〜31 日 · 週約 40 時間 · FSA 優先）&quot;">​</a></h3><h4 id="今週-10-月-13〜18-日" tabindex="-1">今週（10 月 13〜18 日） <a class="header-anchor" href="#今週-10-月-13〜18-日" aria-label="Permalink to &quot;今週（10 月 13〜18 日）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>重点</th><th style="text-align:right;">時間</th><th>10 月 18 日（日）までの目標</th></tr></thead><tbody><tr><td>FSA の深掘り</td><td style="text-align:right;">22–24</td><td>1 周目 80〜100% 以上 + 章末問題</td></tr><tr><td>倫理の残り</td><td style="text-align:right;">6–8</td><td>II(A) 以降の基準に着手</td></tr><tr><td>経済学の仕上げ</td><td style="text-align:right;">3–4</td><td>残り半分を終える</td></tr></tbody></table><h4 id="_10-月-19〜25-日の週" tabindex="-1">10 月 19〜25 日の週 <a class="header-anchor" href="#_10-月-19〜25-日の週" aria-label="Permalink to &quot;10 月 19〜25 日の週&quot;">​</a></h4><ul><li>株式：1 周目をすべて。</li><li>債券：1 周目の大部分。</li><li>FSA の強化：6〜8 時間の混合演習。</li></ul><h4 id="_10-月-26〜31-日の週" tabindex="-1">10 月 26〜31 日の週 <a class="header-anchor" href="#_10-月-26〜31-日の週" aria-label="Permalink to &quot;10 月 26〜31 日の週&quot;">​</a></h4><ul><li>債券を終える。</li><li>ポートフォリオ・マネジメント、コーポレート・イシュアー、オルタナティブ投資。</li><li>倫理のケース演習。</li><li><strong>10 月 31 日（金）までにカリキュラム完了。</strong></li></ul><h3 id="フェーズ-2-—-復習と模試-11-月-1〜16-日" tabindex="-1">フェーズ 2 — 復習と模試（11 月 1〜16 日） <a class="header-anchor" href="#フェーズ-2-—-復習と模試-11-月-1〜16-日" aria-label="Permalink to &quot;フェーズ 2 — 復習と模試（11 月 1〜16 日）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模試</th><th>日付</th><th>メモ</th></tr></thead><tbody><tr><td>模試 1</td><td>11 月 1 日（土）</td><td>本番どおりの時間で。復習は FSA から。</td></tr><tr><td>模試 2</td><td>11 月 8 日（土）</td><td>本番どおりの時間で。週の半ばに最も弱い 2 科目を補強。</td></tr><tr><td>模試 3</td><td>11 月 12 日（水）</td><td>本番どおりの時間で。</td></tr><tr><td>任意の模試 4</td><td>11 月 15 日（土）</td><td>体力と復習の進み具合が許す場合のみ。</td></tr></tbody></table><p>どの復習週も、まず FSA、次に直近の模試で点数が最も低かった科目。記録したミスを解き直し、週に 1 回は核となる公式シートを記憶だけで書き直す。</p><h3 id="フェーズ-3-—-テーパー-11-月-17〜18-日" tabindex="-1">フェーズ 3 — テーパー（11 月 17〜18 日） <a class="header-anchor" href="#フェーズ-3-—-テーパー-11-月-17〜18-日" aria-label="Permalink to &quot;フェーズ 3 — テーパー（11 月 17〜18 日）&quot;">​</a></h3><ul><li>軽い混合問題のみ。模試はやらない。</li><li>倫理、公式、繰り返すミス、電卓の手順、試験当日の段取り。</li><li>睡眠を守る。新しい教材は増やさない。</li></ul><h2 id="週次レビューのテンプレート" tabindex="-1">週次レビューのテンプレート <a class="header-anchor" href="#週次レビューのテンプレート" aria-label="Permalink to &quot;週次レビューのテンプレート&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>予定 / 実績の時間：</span></span>
<span class="line"><span>FSA / 倫理 / その他の科目の進捗：</span></span>
<span class="line"><span>解いた問題数 / 正答率：</span></span>
<span class="line"><span>最も弱い科目とミスのパターン：</span></span>
<span class="line"><span>今なら人に教えられる概念を 1 つ：</span></span>
<span class="line"><span>来週変えることを 1 つ：</span></span></code></pre></div><h2 id="これからの-7-日間-10-月-14〜20-日" tabindex="-1">これからの 7 日間（10 月 14〜20 日） <a class="header-anchor" href="#これからの-7-日間-10-月-14〜20-日" aria-label="Permalink to &quot;これからの 7 日間（10 月 14〜20 日）&quot;">​</a></h2><ul><li>[ ] FSA M1 の章末問題を終え、<strong>M2 従業員報酬</strong>を始める。</li><li>[ ] FSA M3〜M6 を進める（遅れを取り戻す間は骨子だけでも可）。</li><li>[ ] II(A) 以降の倫理を続ける。週に 1 回は短い倫理の問題セットを解く。</li><li>[ ] 経済学の残り半分を終える。</li><li>[ ] 18 日（日）のチェックポイント：FSA 1 周目 80〜100% 以上 + 章末問題、倫理は進行中、経済学は完了。</li><li>[ ] 20 日（月）までに：株式の 1 周目を始める（10 月 19〜25 日の週の始まり）。</li></ul>`,31)])])}const b=a(n,[["render",i]]);export{c as __pageData,b as default};
